function pendingBanner(){const value=intents?.pending;$('#pending').hidden=!value;if(!value)return;$('#pending').innerHTML='<p>A local action is awaiting confirmation. Retry it before making another change.</p><button class="primary" id="retry-pending">Retry local save</button>';$('#retry-pending').onclick=()=>guard(async()=>{await intents.retry();await refresh();await recoverRestore();workspace=null;picker=false;tab='review';renderToken++;note('Local save confirmed.');render();});}
async function refresh(){[session,backupStatus]=await Promise.all([api('/api/session'),api('/api/backup-status')]);if(!intents.checkGeneration(session.storageGeneration)){workspace=null;picker=false;tab='review';note('This browser was restored. An older pending action was cleared.');}pendingBanner();}
async function guard(fn){if(busy)return;busy=true;document.querySelectorAll('button,input,select,textarea').forEach(el=>{if(el.closest('nav,#audio-dock'))return;el.dataset.wasDisabled=el.disabled?'1':'0';el.disabled=true;});try{await fn();}catch(error){note(error.message||'The action could not be completed.',true);if(error.status===409){await refresh();workspace=null;picker=false;render();}}finally{busy=false;document.querySelectorAll('[data-was-disabled]').forEach(el=>{el.disabled=el.dataset.wasDisabled==='1';delete el.dataset.wasDisabled;});pendingBanner();}}
