function rows(cards){return cards.length?cards.map(c=>'<div class="item-row">'+(tab==='library'&&selecting&&c.canManage?'<label class="bulk-check"><input type="checkbox" data-bulk="'+esc(c.id)+'" aria-label="Select '+esc(c.reference)+'"'+(selectedItems.has(c.id)?' checked':'')+'></label>':'')+'<button class="open-item" data-open="'+esc(c.id)+'"><span class="item-mark" aria-hidden="true">'+rowMark(c)+'</span><span class="item-text"><strong>'+esc(displayRef(c.kind==='story'?(c.title||c.reference):c.reference))+'</strong><small>'+esc((c.kind==='story'&&c.title?displayRef(c.passageReference||c.reference)+' · ':'')+rowStatus(c))+'</small></span></button>'+(c.canManage&&!(tab==='library'&&selecting)?'<details class="item-options"><summary aria-label="Options for '+esc(displayRef(c.kind==='story'?(c.title||c.reference):c.reference))+'">⋯</summary><div><label>Stage<select class="stage-select" data-stage="'+esc(c.id)+'" aria-label="Learning stage for '+esc(c.reference)+'">'+['learning','memorized','later'].map(stage=>'<option value="'+stage+'"'+(c.learningStage===stage?' selected':'')+'>'+stageLabel(stage)+'</option>').join('')+'</select></label></div></details>':'')+'</div>').join(''):'<p class="subtle">No items here yet.</p>';}
