 $('#picker-back').onclick=()=>{picker=false;render();};const book=$('#book-choice'),chapter=$('#chapter-choice'),scope=$('#scope-choice'),start=$('#start-choice'),end=$('#end-choice'),kind=$('#item-kind'),summaryRef=$('#summary-reference'),summaryText=$('#summary-text'),summarySource=$('#summary-source'),cardForm=mountCardForm($('#passage-form'),{storage:sessionStorage,key:LOCAL_UI_PREFIX+':card-draft'},cardPictures);
