async function showItemReviewHistory(w){const token=++renderToken;showListen(false);const data=await api('/api/progress?card='+encodeURIComponent(w.card.id));if(token!==renderToken)return;const card=session.cards.find(c=>c.id===w.card.id)||w.card;content.innerHTML='<button class="text-button" id="item-history-back">← Back to this item</button>'+itemReviewHistoryHTML(data,card,{timeZone:session.timeZone,now:session.now,reviewPolicy:session.reviewPolicy});$('#item-history-back').onclick=()=>{if(workspace===w)renderWorkspace();else render();};}
async function savedReviewHistory(){const token=++renderToken;const data=await api('/api/history');if(token!==renderToken)return;content.innerHTML='<button class="text-button" id="review-history-back">← My Progress</button>'+reviewHistoryHTML({reviews:data.reviews,cards:session.cards,timeZone:session.timeZone});$('#review-history-back').onclick=()=>{tab='progress';render();};}
async function progress(token){content.innerHTML='<h1>My Progress</h1><p>Loading confirmed local activity…</p>';const data=await api('/api/progress-overview');if(token!==renderToken)return;const w=data.week;content.innerHTML='<h1>My Progress</h1>'+backupReminderHTML()+'<section class="panel"><h2>This week</h2><p class="subtle">'+esc(friendlyDay(w.start))+' – '+esc(friendlyDay(w.end))+' · '+esc(zoneLabel(session.timeZone))+'</p><dl class="metric-grid"><div><dt>Days with saved practice or review</dt><dd>'+w.daysPracticed+'</dd></div><div><dt>Different items practiced or reviewed</dt><dd>'+w.uniqueItems+'</dd></div><div><dt>Scheduled reviews completed</dt><dd>'+w.scheduledReviews+'</dd></div></dl><p>'+w.practiceCompletions+' practice completions (each saved Read, Listen, or Recall action), separate from scheduled reviews.</p></section><section class="panel"><h2>Your Scripture Journey</h2><p class="subtle">Your chosen stages, not an estimate of mastery.</p>'+data.journey.map(g=>'<div class="journey"><h3>'+(CATEGORY_LABELS[g.kind])+'</h3><p>'+g.learning+' Learning · '+g.memorized+' Memorized · '+g.later+' Later</p></div>').join('')+'</section><section class="panel"><h2>Recent activity</h2>'+(data.recent.length?data.recent.map(e=>'<div class="activity"><strong>'+esc(e.reference)+'</strong><small>'+esc(activityLabel(e.kind))+' · '+esc(dateLabel(e.at,session.timeZone))+'</small>'+(e.canRemove?'<button class="text-button" data-remove="'+esc(e.key)+'" data-revision="'+e.correctionRevision+'">Remove accidental entry</button>':'')+'</div>').join(''):'<p>Your first confirmed practice or review will appear here. Opening a passage or playing audio alone does not record a completion.</p>')+'<p class="subtle">All time: '+data.totalPractice+' practice completions · '+data.totalScheduledReviews+' scheduled reviews.</p><details class="group"><summary>Activity calendar</summary><div id="calendar"></div></details><div class="row"><button class="secondary" id="activity-history">View practice history</button><button class="secondary" id="adaptive-history">Saved review history</button></div></section>';content.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>guard(async()=>{if(!confirm(removalPrompt(data.recent.find(e=>e.key===button.dataset.remove),session.timeZone)))return;await mutate('/api/practice-corrections',{eventKey:button.dataset.remove,action:'remove',revision:Number(button.dataset.revision)});note('Entry removed from practice counts.');render();}));$('#activity-history').onclick=()=>guard(activityHistory);$('#adaptive-history').onclick=()=>guard(savedReviewHistory);renderCalendar(data);bindBackupReminder();}
function renderCalendar(data){calendarController?.dispose();calendarController=mountCalendar($('#calendar'),{data,month:calendarMonth||data.today.slice(0,7),timeZone:session.timeZone,onMonth:month=>{calendarMonth=month;calendarDay=null;},onDay:day=>{calendarDay=day;},onCorrect:event=>guard(async()=>{if(!confirm(removalPrompt(event,session.timeZone)))return;await mutate('/api/practice-corrections',{eventKey:event.key,action:'remove',revision:event.correctionRevision});note('Accidental practice entry removed.');render();}),onError:error=>note(error.message,true)});if(calendarDay)calendarController.selectDay(calendarDay);}
async function activityHistory(){const data=await api('/api/practice-entries?includeRemoved=1');content.innerHTML='<button class="text-button" id="history-back">← My Progress</button><h1>Practice history</h1>'+(data.events.length?data.events.map(e=>'<div class="activity"><strong>'+esc(e.reference)+'</strong><small>'+esc(activityLabel(e.kind))+' · '+esc(dateLabel(e.at,session.timeZone))+(e.removed?' · Removed from counts':'')+'</small><button class="text-button" data-correct="'+esc(e.key)+'" data-revision="'+e.correctionRevision+'" data-action="'+(e.removed?'undo':'remove')+'">'+(e.removed?'Undo removal':'Remove accidental entry')+'</button></div>').join(''):'<p>No practice entries yet.</p>');$('#history-back').onclick=render;content.querySelectorAll('[data-correct]').forEach(button=>button.onclick=()=>guard(async()=>{if(button.dataset.action==='remove'&&!confirm(removalPrompt(data.events.find(e=>e.key===button.dataset.correct),session.timeZone)))return;await mutate('/api/practice-corrections',{eventKey:button.dataset.correct,action:button.dataset.action,revision:Number(button.dataset.revision)});await activityHistory();}));}
async function more(token){const [prefs,cm,backupStatus]=await Promise.all([api('/api/preferences'),api('/api/cm'),api('/api/backup-status')]);if(token!==renderToken)return;content.innerHTML='<h1>More</h1><section class="panel"><h2>Keep a backup</h2><p>Progress is stored only in this browser on this device. Clearing site data can erase it. Download and keep a separate backup; this is not automatic cloud sync. One backup covers Memory progress, selected passages, editable Audio playlists, supported playback/display settings and theme. Typed recall drafts and active playback are browser-local recovery only, not backup history.</p><p class="subtle">'+(backupStatus.lastDownloadedAt?'Last download you confirmed: '+esc(dateLabel(backupStatus.lastDownloadedAt,session.timeZone)):'No saved download has been confirmed yet.')+(backupStatus.reminderDue?' · A backup reminder is due.':'')+'</p><button class="primary" id="export-backup">Download backup</button><div id="download-confirm"></div><details class="group"><summary>Restore a public backup</summary><div><p>A combined backup replaces Memory progress, editable Audio playlists and supported settings. Older Memory backups replace Memory only; older Audio backups add playlists only. Saved outlines are included; older preloaded Stories with saved work remain recoverable. A before-restore recovery copy is kept in this browser, but download a fresh backup first. Only this app’s public browser backup format is accepted.</p><label>Backup JSON<input class="file-input" type="file" id="restore-file" accept="application/json,.json"></label><label class="check"><input type="checkbox" id="restore-confirm">I understand the replacement or additive behavior described above.</label><button class="secondary" id="restore-backup">Restore backup</button></div></details></section><section class="panel"><h2>Review schedule</h2><p>Adaptive uses your saved recall ratings. Charlotte Mason uses an explicitly configured review box. Changing a schedule does not erase previous history.</p><form id="schedule-form"><label>Schedule<select id="schedule-choice"><option value="adaptive"'+(session.reviewPolicy==='adaptive'?' selected':'')+'>Adaptive</option><option value="charlotte-mason"'+(session.reviewPolicy==='charlotte-mason'?' selected':'')+'>Charlotte Mason</option></select></label><label id="cm-rest-setting">Charlotte Mason rest day<select id="rest-day"><option value="">No rest day</option>'+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((day,i)=>'<option value="'+i+'"'+(cm.plan.sabbath===i?' selected':'')+'>'+day+'</option>').join('')+'</select></label><div id="cm-setup" hidden><p>Choose the existing Active items to start in Daily. No item is selected automatically.</p>'+session.cards.filter(c=>c.canManage&&c.studyStatus==='active').map(c=>'<label class="check"><input type="checkbox" name="daily" value="'+esc(c.id)+'">'+esc(c.reference)+'</label>').join('')+'<label class="check"><input type="checkbox" id="cm-confirm">Set up this review box using only my selected items.</label></div><button class="secondary">Save schedule choice</button></form><form id="timezone-form"><label>My timezone<select id="timezone" required>'+zoneOptionsHTML(prefs.timeZone)+'</select></label><p class="subtle">Defaults to this browser’s timezone. Calendar days and review boundaries use this selection.</p><button class="secondary">Save timezone</button></form></section><section class="panel"><h2>Import cards</h2><div id="card-import"></div></section><section class="panel"><h2>About</h2><p>'+esc(ABOUT_TEXT)+'</p><p class="subtle">No account is required. Audio and study data stream online. Your saved memory progress is browser-local and separate from the original standalone apps.</p><button class="secondary" id="sources-button">Sources</button></section>';foldMore(prefs);if($('#card-import'))mountCardImport($('#card-import'),{onImport:importCards,capacity:1000-session.cards.filter(c=>!catalog.some(item=>item.id===c.id)).length});$('#sources-button').onclick=renderSources;$('#export-backup').onclick=()=>guard(exportBackup);$('#restore-backup').onclick=()=>guard(restoreBackup);
 function showSetup(){const active=$('#schedule-choice').value==='charlotte-mason';$('#cm-setup').hidden=!active||!!cm.plan.box;$('#cm-rest-setting').hidden=!active;$('#rest-day').disabled=!active;}
 $('#schedule-choice').onchange=showSetup;showSetup();$('#schedule-form').onsubmit=event=>{event.preventDefault();guard(async()=>{const active=$('#schedule-choice').value==='charlotte-mason',sabbath=$('#rest-day').value===''?null:Number($('#rest-day').value);if(active&&!cm.plan.box){const dailyIds=[...content.querySelectorAll('input[name=daily]:checked')].map(x=>x.value);if(!dailyIds.length||!$('#cm-confirm').checked)throw Error('Choose and explicitly confirm at least one Active item for Daily.');await mutate('/api/cm',{revision:cm.revision,kind:'setup',dailyIds,sabbath,confirmed:true});}else if(cm.plan.box)await mutate('/api/cm',{revision:cm.revision,kind:'settings',active,sabbath});else if(!active){note('Adaptive is already selected. No schedule was created.');return;}note('Review schedule saved. Existing history preserved.');render();});};$('#timezone-form').onsubmit=event=>{event.preventDefault();guard(async()=>{await mutate('/api/preferences',{revision:prefs.revision,timeZone:$('#timezone').value.trim()});note('Timezone saved: '+zoneLabel($('#timezone').value)+'.');render();});};
}
function backupContext(){return {catalog,validateCatalog,books};}
function reminderSettings(){try{const v=JSON.parse(localStorage.getItem(REMINDER_KEY)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}catch{return {};}}
function validPastDate(value){const n=typeof value==='string'?Date.parse(value):NaN;return Number.isFinite(n)&&n<=Date.now()?value:null;}
function rememberAudioSave(at){if(restoreInProgress)return;const value=reminderSettings();if(!validPastDate(value.firstAudioSavedAt)){value.firstAudioSavedAt=validPastDate(at)||new Date().toISOString();try{localStorage.setItem(REMINDER_KEY,JSON.stringify(value));}catch{note('The backup reminder could not be saved. Keep a downloaded backup.',true);}}if(session&&!workspace&&!picker&&!busy)render();}
function backupReminderHTML(){const settings=reminderSettings(),dates=[backupStatus?.firstProgressAt,settings.firstAudioSavedAt].map(validPastDate).filter(Boolean).sort(),download=validPastDate(backupStatus?.lastDownloadedAt),anchor=download&&dates[0]&&download>dates[0]?download:dates[0],snooze=Date.parse(settings.reminderSnoozedUntil||'');if(!dates.length||!anchor||Date.now()-Date.parse(anchor)<7*86400000||Number.isFinite(snooze)&&snooze>Date.now()&&snooze-Date.now()<=2*86400000)return '';return '<aside class="backup-reminder"><strong>Keep your Scripture progress safe</strong><p>This browser holds your progress and playlists. Save a backup somewhere safe.</p><div class="row"><button class="secondary" id="reminder-backup">Download backup</button><button class="text-button" id="snooze-backup">Remind me tomorrow</button></div></aside>';}
function bindBackupReminder(){$('#reminder-backup')?.addEventListener('click',()=>guard(async()=>{tab='more';await more(++renderToken);await exportBackup();}));$('#snooze-backup')?.addEventListener('click',()=>{try{const value=reminderSettings();value.reminderSnoozedUntil=calendarDue(new Date(),1,session.timeZone).toISOString();localStorage.setItem(REMINDER_KEY,JSON.stringify(value));render();}catch{note('The reminder could not be snoozed. Your data is unchanged.',true);}});}
async function snapshotBackup(){const memory=await api('/api/export'),audio=await audioBridge.request('backup-export');if(audio.lists.length&&!validPastDate(reminderSettings().firstAudioSavedAt))rememberAudioSave(new Date().toISOString());return createUnifiedBackup({memory,audio,ui:currentUiBackup(),exportedAt:new Date().toISOString()},backupContext());}
function downloadJSON(backup,name='bible-memory-public-backup'){const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function exportBackup(){const backup=await snapshotBackup();downloadJSON(await withPictures(backup));lastDownload=backup;const target=$('#download-confirm');if(!target){note('Backup download requested. Open More to confirm after saving.');return;}target.innerHTML='<p class="subtle">The download was requested. Check that the file saved before confirming.</p><button class="secondary" id="confirm-download">I saved this backup</button>';$('#confirm-download').onclick=()=>guard(async()=>{const marker=await api('/api/backup-status');await mutate('/api/backup-marker',{revision:marker.revision,exportedRevision:lastDownload.memory.state.revision});lastDownload=null;const settings=reminderSettings();settings.reminderSnoozedUntil=null;try{localStorage.setItem(REMINDER_KEY,JSON.stringify(settings));}catch{}note('Backup download confirmed. Keep the actual file somewhere safe.');render();});note('Backup download requested—not yet confirmed saved.');}
function restoreBanner(message){const box=$('#restore-recovery');box.hidden=false;box.innerHTML='<strong>Restore needs attention</strong><p>'+esc(message)+'</p><div class="row"><button class="secondary" id="retry-restore">Continue restore</button><button class="secondary" id="download-recovery">Download before-restore backup</button></div><p class="subtle">Memory and Audio use different browser stores. This recovery record is kept until both finish; do not clear site data.</p>';$('#retry-restore').onclick=()=>guard(async()=>{await recoverRestore();render();});$('#download-recovery').onclick=()=>{try{const value=JSON.parse(localStorage.getItem(RECOVERY_KEY));if(!value)throw Error();downloadJSON(value,'bible-memory-before-restore');}catch{note('The previous backup could not be read. Do not clear browser storage.',true);}};}
function currentUiBackup(){const value=reminderSettings(),recallPreferences=drafts.readPreference();return {...(recallPreferences?{recallPreferences}:{}),theme:localStorage.getItem(LOCAL_UI_PREFIX+':theme')==='dark'?'dark':'light',reminderSnoozedUntil:value.reminderSnoozedUntil??null,firstAudioSavedAt:value.firstAudioSavedAt??null};}
function sameUi(a,b){return ['theme','reminderSnoozedUntil','firstAudioSavedAt','recallPreferences'].every(key=>JSON.stringify(a?.[key]??null)===JSON.stringify(b?.[key]??null));}
function validUiRecovery(value){return value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).every(key=>['theme','reminderSnoozedUntil','firstAudioSavedAt','recallPreferences'].includes(key))&&['light','dark'].includes(value.theme)&&(!Object.hasOwn(value,'recallPreferences')||value.recallPreferences&&['oral','full','first'].includes(value.recallPreferences.method)&&['verse','passage'].includes(value.recallPreferences.scope)&&Object.keys(value.recallPreferences).every(key=>['method','scope'].includes(key)))&&['reminderSnoozedUntil','firstAudioSavedAt'].every(key=>!Object.hasOwn(value,key)||value[key]===null||typeof value[key]==='string'&&Number.isFinite(Date.parse(value[key]))&&new Date(value[key]).toISOString()===value[key]);}
function restoreUI(value){if(!value)return;if(!validUiRecovery(value))throw Error('The saved display recovery record is invalid. Your recovery backup was kept.');const settings=reminderSettings();for(const key of ['reminderSnoozedUntil','firstAudioSavedAt'])if(Object.hasOwn(value,key))settings[key]=value[key];localStorage.setItem(REMINDER_KEY,JSON.stringify(settings));localStorage.setItem(LOCAL_UI_PREFIX+':theme',value.theme);if(Object.hasOwn(value,'recallPreferences'))drafts.savePreference(value.recallPreferences);setTheme(value.theme);}
async function clearNeverSubmittedRestore(requestId){if(typeof requestId!=='string')return false;try{const exported=await api('/api/export');if(!exported?.state?.receipts||Object.hasOwn(exported.state.receipts,requestId))return false;if(localStorage.getItem(LOCAL_UI_PREFIX+':pending:'+requestId)!==null)return false;const current=JSON.parse(localStorage.getItem(RESTORE_KEY)||'null');if(current?.memoryRequestId!==requestId)return false;localStorage.removeItem(RESTORE_KEY);return localStorage.getItem(RESTORE_KEY)===null;}catch{return false;}}
async function finishRestore(journal){if(journal.ui&&journal.expectedUi){const current=currentUiBackup(),target={...journal.expectedUi,...journal.ui};if(!['theme','reminderSnoozedUntil','firstAudioSavedAt','recallPreferences'].every(key=>JSON.stringify(current[key]??null)===JSON.stringify(journal.expectedUi[key]??null)||JSON.stringify(current[key]??null)===JSON.stringify(target[key]??null)))throw Error('Display or reminder settings changed in another tab. Your recovery backup was kept.');}if(journal.audio)await audioBridge.request('backup-apply',{backup:journal.audio,expected:journal.expectedAudio});restoreUI(journal.ui);localStorage.removeItem(RESTORE_KEY);$('#restore-recovery').hidden=true;await refresh();intents.discardAfterRestore(session.storageGeneration);workspace=null;picker=false;tab='review';renderToken++;note('Public backup restored. Older practice forms and drafts cannot submit into the restored progress.');}
async function recoverRestore(){let journal;try{journal=JSON.parse(localStorage.getItem(RESTORE_KEY)||'null');}catch{restoreBanner('The local restore record could not be read. Download your recovery backup before changing storage.');return;}if(!journal)return;if(journal.version!==1||Object.keys(journal).some(key=>!['version','memoryRequestId','audio','expectedAudio','expectedUi','ui'].includes(key))||journal.ui&&!validUiRecovery(journal.ui)||journal.expectedUi&&!validUiRecovery(journal.expectedUi)||journal.memoryRequestId!==null&&!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(journal.memoryRequestId)){restoreBanner('The saved restore record is invalid. Your recovery backup was kept.');return;}restoreInProgress=true;try{if(journal.memoryRequestId){const exported=await api('/api/export'),receipt=exported.state.receipts[journal.memoryRequestId]?.receipt;if(!receipt?.restored){restoreBanner('Memory restore is not confirmed. Retry the pending local save first. No Audio or display settings were replaced.');return;}if(receipt.storageGeneration!==exported.state.storageGeneration){restoreBanner('Another restore replaced this session. The older Audio restore was not applied. Your before-restore backup is available.');return;}}await finishRestore(journal);}catch(error){restoreBanner(error.message||'The restore did not finish.');note('Restore is not complete. The before-restore backup and retry record were kept.',true);}finally{restoreInProgress=false;}}
async function restoreBackup(){const file=$('#restore-file').files[0];if(!file||!$('#restore-confirm').checked)throw Error('Choose a public backup and confirm replacement first.');if(file.size>400*1024*1024)throw Error('This backup is too large (maximum 400 MB).');let value;try{value=JSON.parse(await file.text());}catch{throw Error('The selected file is not valid JSON.');}if(value&&typeof value==='object'&&Object.hasOwn(value,'cardPictures')){const pictures=await readBackupPictures(value.cardPictures);for(const picture of pictures){const saved=await api.savePicture(new Blob([picture.bytes],{type:picture.mime}));if(saved.id!==picture.id)throw Error('A picture was not confirmed. Nothing else was restored.');}delete value.cardPictures;}if(new Blob([JSON.stringify(value)]).size>6*1024*1024)throw Error('This backup is too large (maximum 6 MiB, not counting pictures).');if(localStorage.getItem(RESTORE_KEY))throw Error('Finish the pending restore before starting another.');const parsed=parseUnifiedBackup(value,backupContext());if(parsed.audio)await audioBridge.request('backup-validate',{backup:parsed.audio});await refresh();if(intents.pending??intents.read())throw Error('Retry the pending local save before restoring.');const before=await snapshotBackup();let audio=parsed.audio;if(parsed.kind==='legacy-audio'){audio={...before.audio,lists:[...before.audio.lists,...audio.lists],current:audio.current};if(!confirm('Add '+parsed.audio.lists.length+' playlists? Existing playlists and all Memory progress will be kept. Importing again adds another copy.'))return;await audioBridge.request('backup-validate',{backup:audio});}const requestId=parsed.memory?crypto.randomUUID():null,journal={version:1,memoryRequestId:requestId,audio,expectedAudio:before.audio,expectedUi:before.ui,ui:parsed.ui};localStorage.setItem(RECOVERY_KEY,JSON.stringify(before));localStorage.setItem(RESTORE_KEY,JSON.stringify(journal));restoreInProgress=true;try{if(parsed.memory)await mutate('/api/restore',{requestId,revision:session.storageRevision,backup:parsed.memory});await finishRestore(journal);render();}catch(error){if(requestId&&await clearNeverSubmittedRestore(requestId))throw Error('Nothing was restored. '+(error.message||'The local retry record could not be preserved.')+' Your before-restore backup was kept; choose the file again to retry.');if([400,404,409,413,422,501].includes(error.status))throw error;restoreBanner(error.message);throw Error('Restore is not complete. A before-restore backup and retry record were kept.');}finally{restoreInProgress=false;}}
function outlineKey(w){return LOCAL_UI_PREFIX+':story-outline:'+w.storageGeneration+':'+encodeURIComponent(w.card.id)+':'+w.card.version;}
function loadOutlineDraft(w,notes){if(notes?.error){w.notesError=notes.error;return;}w.notes=notes;w.outlineDraft=notes.outline;w.outlineConflict=false;try{const raw=localStorage.getItem(outlineKey(w));if(raw){const value=JSON.parse(raw);if(typeof value.outline==='string'&&value.outline.length<=4000&&Number.isSafeInteger(value.revision)){w.outlineDraft=value.outline;w.outlineConflict=value.revision!==notes.revision;}}}catch{w.outlineWarning='This browser could not recover or save its local outline draft. Keep this tab open.';}}
function outlineHTML(w){if(w.loading)return '';if(w.notesError)return '<section class="panel"><h2>My story outline</h2><p class="warning">'+esc(w.notesError)+'</p><button class="secondary" id="retry-outline">Retry outline</button></section>';if(!w.notes)return '';return '<details class="group"><summary>My story outline</summary><div><p class="subtle">Your own notes—not Scripture, an automatic summary, or a rating. Save them to include them in a backup.</p>'+(w.outlineWarning?'<p class="warning">'+esc(w.outlineWarning)+'</p>':'')+(w.outlineConflict?'<p class="warning">The saved outline changed in another tab. Your draft is kept below. Copy it before loading the current saved outline.</p>':'')+'<label>My outline<textarea id="story-outline" rows="5" maxlength="4000">'+esc(w.outlineDraft??w.notes.outline)+'</textarea></label><div class="row"><button class="secondary" id="save-outline"'+(w.outlineConflict||w.outlineDraft===w.notes.outline?' disabled':'')+'>Save my outline</button><button class="text-button" id="discard-outline">Discard local draft / load saved</button></div><p id="outline-status" class="subtle" role="status">Drafts stay only in this browser until saved.</p></div></details>';}
function bindOutline(w){$('#retry-outline')?.addEventListener('click',()=>guard(()=>openItem(w.card.id,w.scheduled)));const input=$('#story-outline');if(!input)return;input.oninput=()=>{if(workspace!==w)return;w.outlineDraft=input.value;try{localStorage.setItem(outlineKey(w),JSON.stringify({revision:w.notes.revision,outline:w.outlineDraft}));$('#outline-status').textContent='Local draft kept. Save my outline includes it in backups.';}catch{$('#outline-status').textContent='This draft could not be preserved. Copy it before leaving.';}$('#save-outline').disabled=busy||w.outlineConflict||w.outlineDraft===w.notes.outline;};$('#save-outline').onclick=()=>guard(async()=>{if(workspace!==w||w.storageGeneration!==session.storageGeneration||w.outlineConflict)throw Error('Reload the current saved outline before saving.');const outline=w.outlineDraft,revision=w.notes.revision,result=await mutate('/api/story-notes',{cardId:w.card.id,contentVersion:w.card.version,revision,outline,storageGeneration:w.storageGeneration});w.notes={cardId:w.card.id,contentVersion:w.card.version,revision:result.revision,outline};try{const raw=localStorage.getItem(outlineKey(w));if(raw){const value=JSON.parse(raw);if(value.revision===revision&&value.outline===outline)localStorage.removeItem(outlineKey(w));}}catch{}note('Your outline was saved. Scripture, practice counts and review dates are unchanged.');if(workspace===w)renderWorkspace();});$('#discard-outline').onclick=()=>guard(async()=>{if(!confirm('Discard this browser’s unsaved outline draft and load the current saved outline?'))return;const notes=await api('/api/story-notes?id='+encodeURIComponent(w.card.id));localStorage.removeItem(outlineKey(w));w.notes=notes;w.outlineDraft=notes.outline;w.outlineConflict=false;w.outlineWarning=null;if(workspace===w)renderWorkspace();});}
function mountSummaryItemRecall(w){
 const root=$('#recall-panel');if(!root)return;
 recallPanel=mountSummaryRecall({root,reference:w.card.reference,text:w.card.text,practiceSaved:hasSavedPractice(w,'recall-practice'),isBlocked:()=>busy||workspace!==w||session.storageGeneration!==w.storageGeneration,onPractice:async()=>{if(busy||workspace!==w)throw Error('Finish the current save first.');busy=true;try{await mutate('/api/practice',{targetId:w.card.id,contentVersion:w.card.version,modality:'recall-practice',storageGeneration:w.storageGeneration});markPracticeSaved(w,'recall-practice');note('Recall practice saved. The review schedule is unchanged.');}finally{busy=false;}},onFinishReview:w.scheduled?async()=>{if(busy)throw Error('Finish the current save first.');busy=true;try{await refresh();if(workspace!==w||session.storageGeneration!==w.storageGeneration||!eligibleReviewTarget(session,w.card.id))throw Error('This summary is no longer due and Active.');const fresh=await api('/api/reveal?id='+encodeURIComponent(w.card.id));if(workspace!==w||fresh.version!==w.card.version)throw Error('This summary changed. Reopen it before reviewing.');w.card=fresh;w.finished=true;renderWorkspace();}finally{busy=false;}}:null});
}
// A verse opens on reciting from memory; Bible stories and summaries keep their Read, Listen and Recall tabs.
function practiceTabs(card){return card.kind==='story'||card.provenance==='user-summary-v1';}
function verseHelp(w){const c=w.card,hints=c.clues?.length||c.explanation?'<details class="group"><summary>Picture clues & explanation</summary><div>'+(c.clues?.length?'<ul>'+c.clues.map(clue=>'<li>'+esc(clue)+'</li>').join('')+'</ul>':'')+(c.explanation?'<p>'+esc(c.explanation)+'</p>':'')+'</div></details>':'';
 return {picture:c.image?{src:c.image,alt:'Memory picture for '+c.reference}:null,onListen:audioRanges(c,books).length?async()=>{showListen(true,c.reference);sendAudio({action:'play',ranges:audioRanges(c,books),hideText:true});}:null,afterReveal:hints};}
function mountItemRecall(w){const root=$('#recall-panel');if(!root)return;const identity={id:w.card.id,version:w.card.version,generation:w.storageGeneration,verseCount:w.verses.length};if(!w.recallLoaded){try{w.recallSnapshot=drafts.readFlowDraft(identity);}catch(error){note(error.message,true);}w.recallLoaded=true;}recallPanel=mountRecallPanel({root,verses:w.verses,saved:w.recallSnapshot?.flow??null,preference:null,simple:verseHelp(w),drafts:w.recallSnapshot?.drafts??emptyRecallDrafts(w.verses.length),compare:compareRecall,isBlocked:()=>busy||workspace!==w||session.storageGeneration!==w.storageGeneration,practiceSaved:hasSavedPractice(w,'recall-practice'),onState:(flow,text)=>{w.recallSnapshot={flow,drafts:text};drafts.saveFlowDraft({...identity,flow,drafts:text});},onPreference:value=>drafts.savePreference(value),onPractice:async()=>{if(busy||workspace!==w||session.storageGeneration!==w.storageGeneration)throw Error('Reload this passage before saving practice.');busy=true;try{await mutate('/api/practice',{targetId:w.card.id,contentVersion:w.card.version,modality:'recall-practice',storageGeneration:w.storageGeneration});markPracticeSaved(w,'recall-practice');note('Recall practice saved. The scheduled review is unchanged.');}finally{busy=false;}},onFinishReview:w.scheduled?async action=>{if(!action?.wholePassage)throw Error('Choose the whole-passage review action.');if(busy)throw Error('Finish the current save first.');busy=true;try{await refresh();if(workspace!==w||session.storageGeneration!==w.storageGeneration||!eligibleReviewTarget(session,w.card.id))throw Error('This item is no longer due and Active. Extra practice is still available.');const fresh=await api('/api/reveal?id='+encodeURIComponent(w.card.id));if(workspace!==w||fresh.version!==w.card.version)throw Error('The passage changed. Reopen it before reviewing.');w.card=fresh;w.finished=true;renderWorkspace();}finally{busy=false;}}:null});}
function renderSources(){showListen(false);content.innerHTML='<button class="text-button" id="sources-back">← More</button><h1>Sources</h1><section class="panel sources"><h2>Berean Standard Bible</h2><p>Scripture text is public domain. <a href="'+sources.scripture.termsUrl+'" target="_blank" rel="noopener noreferrer">Publisher terms</a>.</p><h2>Bible stories</h2><p>'+esc(sources.stories.methodCredit)+' <a href="'+sources.stories.trainingUrl+'" target="_blank" rel="noopener noreferrer">Watch the training</a>.</p><p>Choose an exact BSB passage to retell in your own words. No preloaded Story collection or story pictures are supplied.</p>'+sources.study.sources.map(s=>'<h2>'+esc(s.title)+'</h2><p>'+esc(s.copyright??'')+' '+esc(s.attribution)+'</p><p><a href="'+s.sourceUrl+'" target="_blank" rel="noopener noreferrer">Original source</a> · <a href="'+s.licenseUrl+'" target="_blank" rel="noopener noreferrer">'+esc(s.license)+'</a></p>').join('')+'<p>'+esc(sources.study.changesNotice)+'</p><p class="subtle">'+sources.study.limitations.map(esc).join(' ')+'</p></section>';$('#sources-back').onclick=render;}
function render(){calendarController?.dispose();calendarController=null;recallPanel?.dispose();recallPanel=null;if(!session)return;const token=++renderToken;navigation();if(workspace)return renderWorkspace();showListen(false);if(picker)return passagePicker();if(tab==='review')review();else if(tab==='library')library();else if(tab==='listen'){content.innerHTML='<h1>Listen</h1><p class="subtle">Listen to the Bible, read along, and explore study notes.</p>';showListen(true);}else if(tab==='progress')progress(token).catch(error=>note(error.message,true));else more(token).catch(error=>note(error.message,true));pendingBanner();}
async function boot(){try{const data=await Promise.all(['approved-memory-cards.json','bible-books.json','approved-sources.json'].map(async name=>{const r=await fetch('catalog/'+name,{credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('The approved public catalog could not load.');return r.json();}));const [approved,b,s]=data;catalog=approved;books=b;sources=s;loadPassage=createBSBPassageLoader({books});api=createPublicMemoryApi({catalog,passageLoader:loadPassage});intents=createPublicIntents({api,onChange:pendingBanner});await refresh();api.subscribe(async event=>{if(Number.isSafeInteger(event?.storageGeneration)&&event.storageGeneration<session.storageGeneration)return;if(!restoreInProgress&&(event?.restored||event?.storageGeneration!==undefined&&event.storageGeneration!==session.storageGeneration)){try{await refresh();intents.discardAfterRestore(session.storageGeneration);workspace=null;picker=false;tab='review';renderToken++;note('Public progress changed after a restore. Older open actions were cleared.');render();}catch(error){note(error.message,true);}}else if(!busy&&!restoreInProgress){try{await refresh();if(!workspace&&!picker)render();}catch(error){note(error.message,true);}}});await recoverRestore();render();void audioBridge.request('backup-export').then(value=>{if(value.lists.length)rememberAudioSave(new Date().toISOString());}).catch(()=>{});}catch(error){note(error.message||'This browser could not open durable local progress.',true);content.innerHTML='<h1>Local storage is unavailable</h1><p>No account, online fallback, or temporary in-memory save is used. Try a browser that permits this site’s local storage. Existing data has not been reset.</p>';}}
window.addEventListener('storage',event=>{if(event.key===LOCAL_UI_PREFIX+':theme')setTheme(event.newValue);if(event.key===REMINDER_KEY&&session&&!workspace&&!picker)render();});
setInterval(()=>{if(session&&!workspace&&!picker&&!busy&&['review','progress'].includes(tab))void refresh().then(render).catch(error=>note(error.message,true));},60000);
// The bottom menu can be taller than planned (two-line labels, larger text, the iPhone home bar).
// Measure it so the page and the audio bar always leave room above it.
(()=>{const nav=document.querySelector('nav');if(!nav)return;const set=()=>document.documentElement.style.setProperty('--nav-height',Math.ceil(nav.getBoundingClientRect().height)+'px');set();if(window.ResizeObserver)new ResizeObserver(set).observe(nav);addEventListener('resize',set);})();
void boot();
